// Roll 2 = 98.51 (win): 2.5 x 49.504 = 123.76 paid
DicePage_1.DicePage.setBet('2.5');
DicePage_1.DicePage.placeBet();
balance += (0, diceMath_1.balanceDelta)((0, diceMath_1.money)('2.5'), true, OVER_98);
expectBalance(balance);
cy.wrap((0, diceMath_1.formatMoney)(balance)).should('eq', '3,126.1104');
// Roll 3 = 12.59 (loss): exactly 1.2345 debited
DicePage_1.DicePage.setBet('1.2345');
DicePage_1.DicePage.placeBet();
balance += (0, diceMath_1.balanceDelta)((0, diceMath_1.money)('1.2345'), false, OVER_98);
expectBalance(balance);
cy.wrap((0, diceMath_1.formatMoney)(balance)).should('eq', '3,124.8759');

DicePage_1.DicePage.setDirection('over');
DicePage_1.DicePage.setTarget('98.00');
// cy.dblclick() fires both clicks in one JS tick, which no real mouse can do (see BUGS.md, note N-1).
// Two native clicks in separate tasks, 50 ms apart, model a fast human double-click.
DicePage_1.DicePage.betButton().then(($b) => {
    const button = $b[0];
    button.click();
    return new Cypress.Promise((resolve) => setTimeout(() => {
        button.click();
        resolve();
    }, 50));
});
DicePage_1.DicePage.history().should('have.length.at.least', 1);
DicePage_1.DicePage.betButton().should('not.be.disabled');
// Deterministic check without sleeping: the next deliberate bet must get roll 2.
// If the double-click had placed two bets, this one would get roll 3 (12.59).
DicePage_1.DicePage.placeBet();
DicePage_1.DicePage.rollValue().should('have.text', '98.51');
DicePage_1.DicePage.history().should('have.length', 2);
expectBalance(START + 2 * (0, diceMath_1.balanceDelta)((0, diceMath_1.money)('15'), true, OVER_98));

